K1R6_MODULES = ("identity_k1r6", "k1r6_chain", "k1r6_certifier", "fast_range_k1r6", "k1r6_bridge_resolver")


def verify_k1r6_modules() -> dict:
    """K1R6 module binding: every successor module must be LOADED from its manifest path with its manifest
    hash. (verify_tcb inspects only files under the repository roots; this closes shadowing from elsewhere.)"""
    files = json.loads((CFG / "PRODUCER_MANIFEST.json").read_text())["files"]
    bad = []
    for name in K1R6_MODULES:
        mod = sys.modules.get(name)
        f = str(Path(mod.__file__).resolve()) if mod is not None and getattr(mod, "__file__", None) else None
        want = str((NS / "driver" / f"{name}.py").resolve())
        if f != want or files.get(want) != _sha(want):
            bad.append((name, f))
    if bad:
        raise CusumBridgeRefused(f"K1R6 module binding: successor modules not loaded from the manifest: {bad}")
    return {"k1r6_modules": len(K1R6_MODULES)}


